input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://brickexemplar.com/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?ts ?lbl WHERE {
  ?point a brick:ElectricPower ;
         rdfs:label ?lbl ;
         ref:hasTimeseriesId ?ts .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?label ?ts WHERE {
  ?point a brick:ElectricPower ;
         rdfs:label ?label ;
         brick:ref:hasTimeseriesId ?ts .
} LIMIT 100

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?label WHERE {
  ?point rdfs:label ?label .
} LIMIT 200
